### Initialize QueryClient with SSR defaults in Next.js pages router

Source: https://github.com/tanstack/query/blob/main/docs/framework/react/guides/ssr.md

Sets up a QueryClient instance with default staleTime configuration in the _app.tsx file to prevent immediate refetching on the client after server-side rendering. This wrapper component provides the QueryClientProvider to all pages in the application.

```typescript
// _app.tsx
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'

export default function MyApp({ Component, pageProps }) {
  const [queryClient] = React.useState(
    () =>
      new QueryClient({
        defaultOptions: {
          queries: {
            // With SSR, we usually want to set some default staleTime
            // above 0 to avoid refetching immediately on the client
            staleTime: 60 * 1000,
          },
        },
      }),
  )

  return (
    <QueryClientProvider client={queryClient}>
      <Component {...pageProps} />
    </QueryClientProvider>
  )
}
```

